import { API_URL } from '../config';

export const reviewCode = async (code: string, taskDescription: string) => {
  try {
    const response = await fetch(`${API_URL}/api/review`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        code,
        taskDescription,
      }),
    });

    if (!response.ok) {
      throw new Error('Ошибка при проверке кода');
    }

    const data = await response.json();
    const reviewText = data.choices[0].message.content;

    // Парсим оценку и рекомендации
    const parts = reviewText.split('\n\nРекомендации:');
    const scoreMatch = parts[0].match(/Оценка:\s*(\d+)/);
    const score = scoreMatch ? parseInt(scoreMatch[1]) : 0;

    const suggestions = parts[1]
      ? parts[1].split('\n')
          .map((s: string) => s.trim())
          .filter((s: string) => s && !s.match(/рекомендации|улучшения/i))
      : [];

    return {
      code_review: reviewText,
      review_score: score,
      review_suggestions: suggestions,
    };
  } catch (error) {
    console.error('Error reviewing code:', error);
    throw error;
  }
};
